-- DRAFT: apply only to a disposable LOCAL database until migration approval.
-- Additive tables; no legacy rows, credentials, sessions or grants are changed.
PRAGMA foreign_keys=ON;
CREATE TABLE cm_site_admins(account_id TEXT PRIMARY KEY REFERENCES member_accounts(id));
CREATE TABLE cm_project_settings(project_id TEXT PRIMARY KEY REFERENCES studio_projects(id),kind TEXT NOT NULL DEFAULT 'web' CHECK(kind IN('web','ios')),next_goal TEXT NOT NULL DEFAULT '');
CREATE TABLE cm_roles(project_id TEXT NOT NULL REFERENCES studio_projects(id),account_id TEXT NOT NULL REFERENCES member_accounts(id),role TEXT NOT NULL CHECK(role IN('creator','tester')),PRIMARY KEY(project_id,account_id));
CREATE TABLE cm_invites(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES studio_projects(id),token_hash TEXT UNIQUE NOT NULL,role TEXT NOT NULL CHECK(role IN('creator','tester')),created_by TEXT NOT NULL REFERENCES member_accounts(id),expires_at INTEGER NOT NULL,used_by TEXT REFERENCES member_accounts(id),used_at INTEGER,revoked_at INTEGER);
CREATE TABLE cm_assets(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES studio_projects(id),storage_key TEXT UNIQUE NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL,uploaded_by TEXT NOT NULL REFERENCES member_accounts(id),created_at TEXT NOT NULL);
CREATE TABLE cm_builds(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,project_id TEXT NOT NULL REFERENCES studio_projects(id),task_id TEXT REFERENCES studio_tasks(id),title TEXT NOT NULL,version_label TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL CHECK(kind IN('web','ios')),preview_url TEXT,commit_url TEXT,previous_id TEXT REFERENCES cm_builds(id),after_asset_id TEXT REFERENCES cm_assets(id),created_by TEXT NOT NULL REFERENCES member_accounts(id),client_id TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,version_label),UNIQUE(created_by,client_id));
CREATE INDEX cm_build_project ON cm_builds(project_id,seq);
CREATE TABLE cm_feedback(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES studio_projects(id),build_id TEXT NOT NULL REFERENCES cm_builds(id),kind TEXT NOT NULL CHECK(kind IN('love','idea','confused')),body TEXT NOT NULL,author_id TEXT NOT NULL REFERENCES member_accounts(id),client_id TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(author_id,client_id));
CREATE INDEX cm_feedback_project ON cm_feedback(project_id,created_at,id);
CREATE TABLE cm_replies(id TEXT PRIMARY KEY,feedback_id TEXT NOT NULL REFERENCES cm_feedback(id),author_id TEXT NOT NULL REFERENCES member_accounts(id),body TEXT NOT NULL,client_id TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(author_id,client_id));
CREATE TABLE cm_journeys(feedback_id TEXT PRIMARY KEY REFERENCES cm_feedback(id),task_id TEXT UNIQUE NOT NULL REFERENCES studio_tasks(id),created_by TEXT NOT NULL REFERENCES member_accounts(id),created_at TEXT NOT NULL);
CREATE TABLE cm_retests(id TEXT PRIMARY KEY,feedback_id TEXT NOT NULL REFERENCES cm_feedback(id),build_id TEXT NOT NULL REFERENCES cm_builds(id),requested_by TEXT NOT NULL REFERENCES member_accounts(id),tester_id TEXT NOT NULL REFERENCES member_accounts(id),outcome TEXT NOT NULL DEFAULT 'waiting' CHECK(outcome IN('waiting','better','confused')),note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,answered_at TEXT,UNIQUE(feedback_id,build_id));
CREATE TABLE cm_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL REFERENCES studio_projects(id),actor_id TEXT NOT NULL REFERENCES member_accounts(id),kind TEXT NOT NULL,target_id TEXT NOT NULL,build_id TEXT,created_at TEXT NOT NULL);
CREATE INDEX cm_events_project ON cm_events(project_id,seq);
CREATE TABLE cm_visits(project_id TEXT NOT NULL REFERENCES studio_projects(id),account_id TEXT NOT NULL REFERENCES member_accounts(id),last_seq INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(project_id,account_id));
